import Foundation

struct Habit: Identifiable, Codable, Equatable {
    var id = UUID()
    var name: String
    var days: Set<String> = []   // one "2026-11-10" text per day that was done
}

enum DayKey {
    static func key(for date: Date, calendar: Calendar = .current) -> String {
        let parts = calendar.dateComponents([.year, .month, .day], from: date)
        return String(format: "%04ld-%02ld-%02ld", parts.year ?? 0, parts.month ?? 0, parts.day ?? 0)
    }
}

extension Habit {
    func isDone(on date: Date, calendar: Calendar = .current) -> Bool {
        days.contains(DayKey.key(for: date, calendar: calendar))
    }

    // Days in a row, counting back from today. If today is not done yet, the streak is
    // still alive when yesterday is done, so the user does not lose it before the day ends.
    func currentStreak(today: Date = .now, calendar: Calendar = .current) -> Int {
        var day = today
        if !isDone(on: day, calendar: calendar) {
            guard let yesterday = calendar.date(byAdding: .day, value: -1, to: day) else { return 0 }
            day = yesterday
        }
        var count = 0
        while isDone(on: day, calendar: calendar) {
            count += 1
            guard let previous = calendar.date(byAdding: .day, value: -1, to: day) else { break }
            day = previous
        }
        return count
    }
}

import Foundation
import Observation

@Observable
final class HabitStore {
    private let defaults: UserDefaults
    private let storageKey = "habits.v1"

    var habits: [Habit] {
        didSet { save() }
    }

    init(defaults: UserDefaults = .standard) {
        self.defaults = defaults
        if let data = defaults.data(forKey: "habits.v1"),
           let saved = try? JSONDecoder().decode([Habit].self, from: data) {
            habits = saved
        } else {
            habits = []
        }
    }

    func add(name: String) {
        let clean = name.trimmingCharacters(in: .whitespaces)
        guard !clean.isEmpty else { return }
        habits.append(Habit(name: clean))
    }

    func toggleToday(_ habit: Habit, today: Date = .now) {
        guard let index = habits.firstIndex(where: { $0.id == habit.id }) else { return }
        let key = DayKey.key(for: today)
        if habits[index].days.contains(key) {
            habits[index].days.remove(key)
        } else {
            habits[index].days.insert(key)
        }
    }

    func delete(at offsets: IndexSet) {
        habits.remove(atOffsets: offsets)
    }

    private func save() {
        if let data = try? JSONEncoder().encode(habits) {
            defaults.set(data, forKey: storageKey)
        }
    }
}

