import Foundation

struct Recipe: Identifiable, Codable, Hashable {
    let id: String
    let name: String
    let category: String?
    let area: String?
    let instructions: String?
    let thumbnail: URL?

    enum CodingKeys: String, CodingKey {
        case id = "idMeal"
        case name = "strMeal"
        case category = "strCategory"
        case area = "strArea"
        case instructions = "strInstructions"
        case thumbnail = "strMealThumb"
    }
}

// The service answers {"meals": [...]} and uses null, not an empty list, when nothing matches.
struct RecipeResponse: Codable {
    let meals: [Recipe]?
}

import Foundation

enum RecipeError: LocalizedError {
    case badURL
    case badStatus(Int)

    var errorDescription: String? {
        switch self {
        case .badURL: return "The search address is not valid."
        case .badStatus(let code): return "The server answered with error \(code)."
        }
    }
}

protocol RecipeService {
    func search(_ text: String) async throws -> [Recipe]
}

struct MealDBService: RecipeService {
    func search(_ text: String) async throws -> [Recipe] {
        guard var parts = URLComponents(string: "https://www.themealdb.com/api/json/v1/1/search.php") else {
            throw RecipeError.badURL
        }
        parts.queryItems = [URLQueryItem(name: "s", value: text)]
        guard let url = parts.url else { throw RecipeError.badURL }

        let (data, response) = try await URLSession.shared.data(from: url)
        if let http = response as? HTTPURLResponse, !(200..<300).contains(http.statusCode) {
            throw RecipeError.badStatus(http.statusCode)
        }
        return try JSONDecoder().decode(RecipeResponse.self, from: data).meals ?? []
    }
}

import Foundation
import Observation

@Observable
@MainActor
final class RecipeViewModel {
    enum State: Equatable {
        case idle
        case loading
        case loaded([Recipe])
        case failed(String)
    }

    var query = ""
    private(set) var state: State = .idle
    private let service: RecipeService
    private var searchTask: Task<Void, Never>?

    init(service: RecipeService = MealDBService()) {
        self.service = service
    }

    // Called whenever the search text changes. Waits a moment so we do not call the server on every key.
    func queryChanged() {
        searchTask?.cancel()
        let text = query.trimmingCharacters(in: .whitespaces)
        guard text.count >= 2 else {
            state = .idle
            return
        }
        searchTask = Task {
            try? await Task.sleep(for: .milliseconds(400))
            guard !Task.isCancelled else { return }
            await load(text)
        }
    }

    func load(_ text: String) async {
        state = .loading
        do {
            let recipes = try await service.search(text)
            guard !Task.isCancelled else { return }
            state = .loaded(recipes)
        } catch is CancellationError {
            return
        } catch {
            state = .failed(error.localizedDescription)
        }
    }
}

