import Foundation

struct Product: Identifiable, Codable, Hashable {
    let id: Int
    let title: String
    let price: Double
    let description: String
    let category: String
    let image: URL

    // Money is kept in whole cents everywhere in the cart, so there are no rounding surprises.
    var priceCents: Int { Int((price * 100).rounded()) }
}

struct CartLine: Identifiable, Codable, Equatable {
    let productID: Int
    let title: String
    let priceCents: Int
    var quantity: Int

    var id: Int { productID }
    var lineTotalCents: Int { priceCents * quantity }
}

extension Int {
    // 4990 -> "$49.90"
    var asMoney: String {
        let sign = self < 0 ? "-" : ""
        let value = abs(self)
        return "\(sign)$\(value / 100).\(String(format: "%02d", value % 100))"
    }
}

import Foundation
import Observation

@Observable
final class CartStore {
    private let defaults: UserDefaults

    private(set) var lines: [CartLine] {
        didSet { save() }
    }

    init(defaults: UserDefaults = .standard) {
        self.defaults = defaults
        if let data = defaults.data(forKey: "cart.v1"),
           let saved = try? JSONDecoder().decode([CartLine].self, from: data) {
            lines = saved
        } else {
            lines = []
        }
    }

    var totalCents: Int { lines.reduce(0) { $0 + $1.lineTotalCents } }
    var itemCount: Int { lines.reduce(0) { $0 + $1.quantity } }

    func add(_ product: Product) {
        if let index = lines.firstIndex(where: { $0.productID == product.id }) {
            lines[index].quantity += 1
        } else {
            lines.append(CartLine(productID: product.id, title: product.title,
                                  priceCents: product.priceCents, quantity: 1))
        }
    }

    func change(_ line: CartLine, by delta: Int) {
        guard let index = lines.firstIndex(where: { $0.productID == line.productID }) else { return }
        lines[index].quantity += delta
        if lines[index].quantity <= 0 { lines.remove(at: index) }
    }

    // Demo only: this clears the cart and takes no payment.
    func placeDemoOrder() {
        lines = []
    }

    private func save() {
        if let data = try? JSONEncoder().encode(lines) {
            defaults.set(data, forKey: "cart.v1")
        }
    }
}

import Foundation
import Observation

@Observable
@MainActor
final class ShopViewModel {
    enum State {
        case loading
        case ready([Product])
        case failed(String)
    }

    private(set) var state: State = .loading

    func load() async {
        state = .loading
        do {
            guard let url = URL(string: "https://fakestoreapi.com/products") else { return }
            let (data, response) = try await URLSession.shared.data(from: url)
            if let http = response as? HTTPURLResponse, !(200..<300).contains(http.statusCode) {
                state = .failed("The shop answered with error \(http.statusCode).")
                return
            }
            state = .ready(try JSONDecoder().decode([Product].self, from: data))
        } catch {
            state = .failed("Could not load products. Check your connection and try again.")
        }
    }
}

