import Foundation
import HealthKit

struct DaySteps: Identifiable, Equatable {
    let date: Date
    let steps: Int
    var id: Date { date }
}

enum HealthError: LocalizedError {
    case unavailable

    var errorDescription: String? {
        "Health data is not available on this device."
    }
}

protocol HealthService {
    func requestAccess() async throws
    func lastDays(_ count: Int) async throws -> [DaySteps]
}

// The real service. It needs the HealthKit capability and the usage text from the lesson.
final class HealthKitService: HealthService {
    private let store = HKHealthStore()
    private let stepType = HKQuantityType(.stepCount)

    func requestAccess() async throws {
        guard HKHealthStore.isHealthDataAvailable() else { throw HealthError.unavailable }
        // For read access iOS never tells the app whether the user said yes or no.
        try await store.requestAuthorization(toShare: [], read: [stepType])
    }

    func lastDays(_ count: Int) async throws -> [DaySteps] {
        let calendar = Calendar.current
        let today = calendar.startOfDay(for: .now)
        guard let start = calendar.date(byAdding: .day, value: -(count - 1), to: today),
              let end = calendar.date(byAdding: .day, value: 1, to: today) else { return [] }
        let predicate = HKQuery.predicateForSamples(withStart: start, end: end)

        return try await withCheckedThrowingContinuation { continuation in
            let query = HKStatisticsCollectionQuery(
                quantityType: stepType,
                quantitySamplePredicate: predicate,
                options: .cumulativeSum,
                anchorDate: start,
                intervalComponents: DateComponents(day: 1)
            )
            query.initialResultsHandler = { _, results, error in
                if let error {
                    continuation.resume(throwing: error)
                    return
                }
                var days: [DaySteps] = []
                results?.enumerateStatistics(from: start, to: end) { statistics, _ in
                    let value = statistics.sumQuantity()?.doubleValue(for: .count()) ?? 0
                    days.append(DaySteps(date: statistics.startDate, steps: Int(value)))
                }
                continuation.resume(returning: days)
            }
            store.execute(query)
        }
    }
}

// Made-up numbers for the Simulator, which has no step data, and for tests.
struct FakeHealthService: HealthService {
    func requestAccess() async throws {}

    func lastDays(_ count: Int) async throws -> [DaySteps] {
        let calendar = Calendar.current
        let sample = [4200, 8800, 6100, 10250, 7300, 9100, 5400]
        return (0..<count).map { offset in
            let day = calendar.date(byAdding: .day, value: -(count - 1 - offset), to: calendar.startOfDay(for: .now)) ?? .now
            return DaySteps(date: day, steps: sample[offset % sample.count])
        }
    }
}

import Foundation

enum StepMath {
    // 0...1 for the progress bar. Never above 1, never below 0.
    static func progress(steps: Int, goal: Int) -> Double {
        guard goal > 0 else { return 0 }
        return min(max(Double(steps) / Double(goal), 0), 1)
    }

    static func average(_ days: [DaySteps]) -> Int {
        guard !days.isEmpty else { return 0 }
        return days.reduce(0) { $0 + $1.steps } / days.count
    }

    static func daysMetGoal(_ days: [DaySteps], goal: Int) -> Int {
        days.filter { $0.steps >= goal }.count
    }
}

import Foundation
import Observation

@Observable
@MainActor
final class FitnessViewModel {
    enum State {
        case loading
        case ready([DaySteps])
        case failed(String)
    }

    let goal = 8000
    private(set) var state: State = .loading
    private let service: HealthService

    init(service: HealthService) {
        self.service = service
    }

    func load() async {
        state = .loading
        do {
            try await service.requestAccess()
            state = .ready(try await service.lastDays(7))
        } catch {
            state = .failed(error.localizedDescription)
        }
    }

    var today: DaySteps? {
        if case .ready(let days) = state { return days.last }
        return nil
    }
}

import SwiftUI
import Charts

struct FitnessView: View {
    @State private var model: FitnessViewModel

    init(service: HealthService) {
        _model = State(initialValue: FitnessViewModel(service: service))
    }

    var body: some View {
        NavigationStack {
            Group {
                switch model.state {
                case .loading:
                    ProgressView()
                case .failed(let message):
                    VStack(spacing: 12) {
                        Text(message)
                        Button("Try again") { Task { await model.load() } }
                            .buttonStyle(.borderedProminent)
                    }
                case .ready(let days):
                    ScrollView {
                        VStack(alignment: .leading, spacing: 16) {
                            summary(days)
                            chart(days)
                            Text("Met the goal on \(StepMath.daysMetGoal(days, goal: model.goal)) of \(days.count) days. Average: \(StepMath.average(days)) steps.")
                                .font(.callout)
                                .foregroundStyle(.secondary)
                        }
                        .padding()
                    }
                }
            }
            .navigationTitle("Steps")
        }
        .task { await model.load() }
    }

    private func summary(_ days: [DaySteps]) -> some View {
        let steps = days.last?.steps ?? 0
        return VStack(alignment: .leading, spacing: 6) {
            Text("Today").font(.caption).foregroundStyle(.secondary)
            Text("\(steps)").font(.system(size: 52, weight: .bold))
            ProgressView(value: StepMath.progress(steps: steps, goal: model.goal))
            Text("Goal: \(model.goal) steps").font(.caption)
        }
    }

    private func chart(_ days: [DaySteps]) -> some View {
        Chart {
            ForEach(days) { day in
                BarMark(
                    x: .value("Day", day.date, unit: .day),
                    y: .value("Steps", day.steps)
                )
                .foregroundStyle(day.steps >= model.goal ? Color.green : Color.blue)
            }
            RuleMark(y: .value("Goal", model.goal))
                .lineStyle(StrokeStyle(lineWidth: 1, dash: [4]))
                .foregroundStyle(.orange)
        }
        .frame(height: 220)
        .accessibilityLabel("Bar chart of steps for the last seven days")
    }
}

