import Foundation

struct ChatMessage: Identifiable, Codable, Equatable {
    enum Role: String, Codable {
        case user
        case assistant
    }

    var id = UUID()
    let role: Role
    var text: String
}

enum History {
    // The model has no memory, so each request carries the conversation again.
    // Sending only the latest messages keeps requests small and cheap.
    static func recent(_ messages: [ChatMessage], limit: Int = 12) -> [ChatMessage] {
        Array(messages.suffix(limit))
    }
}

import Foundation

protocol AIService {
    // Streams the growing reply. Each value is the whole text so far.
    func reply(to history: [ChatMessage]) -> AsyncThrowingStream<String, Error>
}

// Makes up an answer word by word, so you can build and test the whole app
// with no key, no server and no cost.
struct FakeAIService: AIService {
    func reply(to history: [ChatMessage]) -> AsyncThrowingStream<String, Error> {
        AsyncThrowingStream { continuation in
            let task = Task {
                let question = history.last?.text ?? ""
                let words = "You asked: \(question). This is a made-up answer. Connect the app to your own server to get real AI replies.".split(separator: " ")
                var text = ""
                for word in words {
                    if Task.isCancelled { break }
                    try? await Task.sleep(for: .milliseconds(120))
                    text += (text.isEmpty ? "" : " ") + word
                    continuation.yield(text)
                }
                continuation.finish()
            }
            continuation.onTermination = { _ in task.cancel() }
        }
    }
}

// Talks to YOUR server. The secret AI key lives on that server, never in this app.
// Contract: POST {"messages":[{"role":"user","text":"..."}]} and the server streams back plain text.
struct ServerAIService: AIService {
    let endpoint: URL

    func reply(to history: [ChatMessage]) -> AsyncThrowingStream<String, Error> {
        AsyncThrowingStream { continuation in
            let task = Task {
                do {
                    var request = URLRequest(url: endpoint)
                    request.httpMethod = "POST"
                    request.setValue("application/json", forHTTPHeaderField: "Content-Type")
                    request.httpBody = try JSONEncoder().encode(["messages": History.recent(history)])

                    let (bytes, response) = try await URLSession.shared.bytes(for: request)
                    if let http = response as? HTTPURLResponse, !(200..<300).contains(http.statusCode) {
                        throw URLError(.badServerResponse)
                    }
                    var text = ""
                    for try await character in bytes.characters {
                        text.append(character)
                        continuation.yield(text)
                    }
                    continuation.finish()
                } catch {
                    continuation.finish(throwing: error)
                }
            }
            continuation.onTermination = { _ in task.cancel() }
        }
    }
}

import Foundation
import Observation

@Observable
@MainActor
final class ChatViewModel {
    private(set) var messages: [ChatMessage]
    private(set) var streaming: String?
    private(set) var errorText: String?
    private let service: AIService
    private let defaults: UserDefaults
    private var job: Task<Void, Never>?

    init(service: AIService, defaults: UserDefaults = .standard) {
        self.service = service
        self.defaults = defaults
        if let data = defaults.data(forKey: "chat.v1"),
           let saved = try? JSONDecoder().decode([ChatMessage].self, from: data) {
            messages = saved
        } else {
            messages = []
        }
    }

    var isReplying: Bool { job != nil }

    func send(_ text: String) {
        let clean = text.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !clean.isEmpty, !isReplying else { return }
        errorText = nil
        messages.append(ChatMessage(role: .user, text: clean))
        save()
        streaming = ""

        let history = History.recent(messages)
        job = Task {
            var latest = ""
            do {
                for try await partial in service.reply(to: history) {
                    latest = partial
                    streaming = partial
                }
            } catch is CancellationError {
                // The user pressed Stop. Keep what we have.
            } catch {
                errorText = "Something went wrong. Please try again."
            }
            finish(with: latest)
        }
    }

    func stop() {
        job?.cancel()
    }

    func clear() {
        stop()
        messages = []
        save()
    }

    private func finish(with text: String) {
        if !text.isEmpty {
            messages.append(ChatMessage(role: .assistant, text: text))
            save()
        }
        streaming = nil
        job = nil
    }

    private func save() {
        if let data = try? JSONEncoder().encode(messages) {
            defaults.set(data, forKey: "chat.v1")
        }
    }
}

