        Video(title: "Apple HLS sample (adaptive)",
              url: URL(string: "https://devstreaming-cdn.apple.com/videos/streaming/examples/img_bipbop_adv_example_fmp4/master.m3u8")!,
              note: "Adaptive stream with several qualities"),
